function lerPorta(texto: string): number {
  const cfg: unknown = JSON.parse(texto);
  if (
    typeof cfg === "object" &&
    cfg !== null &&
    "porta" in cfg &&
    typeof cfg.porta === "number"
  ) {
    return cfg.porta;
  }
  return 3000;
}

console.log(lerPorta('{"porta":8080}'));   // 8080
console.log(lerPorta('{"porta":"8080"}')); // 3000
console.log(lerPorta("[]"));               // 3000

type Nivel = "info" | "aviso" | "erro";

const cores = {
  info: "azul",
  aviso: "amarelo",
  erro: "vermelho",
} as const satisfies Record<Nivel, string>;

const corErro = cores.erro; // "vermelho"

function pintar(nivel: Nivel, texto: string): string {
  return `[${cores[nivel]}] ${texto}`;
}

console.log(pintar("erro", "disco cheio")); // [vermelho] disco cheio
console.log(corErro.length);                // 8

function garantir<T>(valor: T, msg: string): asserts valor is NonNullable<T> {
  if (valor === undefined || valor === null) throw new Error(msg);
}

const stock = new Map<string, number>([["cafe", 3]]);

function retirar(produto: string, qtd: number): number {
  const atual = stock.get(produto);
  garantir(atual, `produto desconhecido: ${produto}`);
  const restante = atual - qtd;
  stock.set(produto, restante);
  return restante;
}

console.log(retirar("cafe", 1)); // 2
try {
  retirar("cha", 1);
} catch (e) {
  if (e instanceof Error) console.log(e.message); // produto desconhecido: cha
}

interface Linha { preco: number; qtd: number }

function eLinha(v: unknown): v is Linha {
  return (
    typeof v === "object" &&
    v !== null &&
    "preco" in v &&
    typeof v.preco === "number" &&
    "qtd" in v &&
    typeof v.qtd === "number"
  );
}

function totalEncomenda(json: string): number | null {
  const dados: unknown = JSON.parse(json);
  if (typeof dados !== "object" || dados === null || !("linhas" in dados)) return null;
  const bruto = dados.linhas;               // unknown
  if (!Array.isArray(bruto)) return null;
  const linhas: unknown[] = bruto;          // travar o any[] do Array.isArray
  let total = 0;
  for (const linha of linhas) {
    if (!eLinha(linha)) return null;
    total += linha.preco * linha.qtd;
  }
  return total;
}

console.log(totalEncomenda('{"linhas":[{"preco":2.5,"qtd":2},{"preco":1,"qtd":3}]}')); // 8
console.log(totalEncomenda('{"linhas":[{"preco":"2.5","qtd":2}]}'));                  // null
console.log(totalEncomenda('{"itens":[]}'));                                          // null
